function parseLLM(j) {
  let o = j && j.output !== undefined ? j.output : j;
  if (o && typeof o.text === 'string' && o.output === undefined && Object.keys(o).length === 1) o = o.text;
  if (typeof o === 'string') {
    const m = o.match(/\{[\s\S]*\}/);
    try { o = JSON.parse(m ? m[0] : o); } catch (e) { o = { _raw: o }; }
  }
  if (o && o.output && typeof o.output === 'object') o = o.output;
  return o || {};
}

const d = $('Decide Next Step').first().json;
const o = parseLLM($input.first().json);
const body = String(o.body || o._raw || '').trim();
return [{ json: { ...d, body, ok: body.length > 20 } }];

const f = $('Prepare Follow-up').first().json;
const r = $input.first().json;
const now = new Date().toISOString();
return [{ json: { message_key: `${f.prospect_id}-followup${f.n}-${Date.now()}`, prospect_id: f.prospect_id, email: f.email, domain: f.domain,
  kind: `followup_${f.n}`, subject: /^re:/i.test(f.first_subject) ? f.first_subject : 'Re: ' + f.first_subject, body: f.body, quality_score: '', status: 'sent',
  thread_id: r.threadId || f.thread_id, gmail_message_id: r.id || '', created_at: now, sent_at: now } }];

